  handleChangeColourSetBlock = (colourSetId, blockId) => {
    let selectedBlocks = { ...this.state.selectedBlocks };
    selectedBlocks[colourSetId] = blockId;
    this.setState({
      selectedBlocks,
    });
  };

  handleChangeColourSetBlocks = (setsAndBlocks) => {
    const { coloursJSON, optionValue_version } = this.state;
    let selectedBlocks = {};
    for (const colourSetId of Object.keys(coloursJSON)) {
      selectedBlocks[colourSetId] = "-1";
    }
    const skippedColourSets = [];
    for (const [int_colourSetId, presetIndex] of setsAndBlocks) {
      // we store presetIndex in the cookie, not blockId
      const colourSetId = int_colourSetId.toString();
      if (!(colourSetId in coloursJSON)) {
        skippedColourSets.push(colourSetId);
        continue;
      }
      const blockIdAndBlock = Object.entries(coloursJSON[colourSetId].blocks).find(([, block]) => block.presetIndex === presetIndex);
      if (blockIdAndBlock === undefined) {
        skippedColourSets.push(colourSetId);
        continue;
      }
      const blockId = blockIdAndBlock[0];
      if (Object.keys(coloursJSON[colourSetId].blocks[blockId].validVersions).includes(optionValue_version.MCVersion)) {
        selectedBlocks[colourSetId] = blockId;
      }
    }
    /* Раньше пресет с неизвестным presetIndex просто молча терялся —
       пользователь видел, что часть блоков не применилась, но не знал почему. */
    if (skippedColourSets.length > 0) {
      console.warn("Preset blocks skipped, unknown colour set or presetIndex:", skippedColourSets);
      if (this.props.onCorruptedPreset) this.props.onCorruptedPreset();
    }
    this.setState({
      selectedBlocks,
    });
  };

  /* ------------------------------------------------------------------------
     Этап 3.6 / 3.7 — анализ картинки и автопалитра.
     ------------------------------------------------------------------------ */

  /* Уменьшенная копия картинки для анализа: полная картинка не нужна,
     а 96x96 — это меньше десяти тысяч точек, и k-means отрабатывает
     мгновенно. */
  sampleImageData = (image) => {
    const size = 96;
    const canvas = document.createElement("canvas");
    canvas.width = size;
    canvas.height = size;
    const context = canvas.getContext("2d");
    context.imageSmoothingEnabled = true;
    context.drawImage(image, 0, 0, size, size);
    return context.getImageData(0, 0, size, size);
  };

  /* Доминирующие цвета картинки и наборы блоков, которые в ней есть. */
  updateImageAnalysis = () => {
    const { uploadedImage, uploadedImage_isPlaceholder, coloursJSON } = this.state;
    /* Плейсхолдер — это картинка «загрузите файл», а не работа
       пользователя. Анализировать её нельзя: иначе автопалитра
       предложила бы блоки под иконкой загрузки, а в списке палитры
       помечались бы цвета, которых в работе нет. */
    if (
      uploadedImage_isPlaceholder ||
      !uploadedImage ||
      !uploadedImage.complete ||
      !uploadedImage.naturalWidth
    ) {
      if (this.state.imageColours.length > 0) {
        this.setState({ imageColours: [], imageColourSetIds: new Set() });
      }
      return;
    }
    const clusters = findDominantColours(this.sampleImageData(uploadedImage), IMAGE_ANALYSIS_CLUSTERS);
    const colourSetIds = colourSetsPresentInImage(clusters, coloursJSON);
    this.setState({ imageColours: clusters, imageColourSetIds: colourSetIds });
  };

  /* Автопалитра: блоки подбираются под цвета картинки. */
  handleAutoPalette = (count) => {
    const { coloursJSON, optionValue_version, imageColours } = this.state;
    if (!imageColours || imageColours.length === 0) {
      this.setState({ autoPaletteResult: { applied: 0, requested: count, empty: true } });
      return;
    }
    const wanted = Math.max(1, Math.min(32, Math.round(count) || 1));
    const suggestions = suggestBlocksForColours(
      imageColours.slice(0, wanted),
      coloursJSON,
      optionValue_version.MCVersion
    );
    const selectedBlocks = {};
    for (const colourSetId of Object.keys(coloursJSON)) {
      selectedBlocks[colourSetId] = "-1";
    }
    let applied = 0;
    for (const suggestion of suggestions) {
      if (!suggestion.blockId) continue;
      selectedBlocks[suggestion.colourSetId] = suggestion.blockId;
      applied += 1;
    }
    this.setState({ selectedBlocks, autoPaletteResult: { applied, requested: wanted, empty: false } });
  };

  handleToggleColourTone = (colourSetId, tone) => {    let disabledTones = { ...this.state.disabledTones };

    const set = new Set(disabledTones[colourSetId] || []);
    disabledTones[colourSetId] = set;

    if (set.has(tone))
      set.delete(tone);
    else
      set.add(tone);

    this.setState({
      disabledTones,
    });
  };

  onOptionChange_modeNBTOrMapdat = (e) => {
    const mode = parseInt(e.target.value);
    this.setState({ optionValue_modeNBTOrMapdat: mode });
    if (mode === MapModes.SCHEMATIC_NBT.uniqueId) {
      this.setState({ optionValue_staircasing: MapModes.SCHEMATIC_NBT.staircaseModes.VALLEY.uniqueId });
    } else {
      this.setState({ optionValue_staircasing: MapModes.MAPDAT.staircaseModes.ON_UNOBTAINABLE.uniqueId });
    }
  };

  onOptionChange_version = (e) => {
    const { coloursJSON } = this.state;
    const mcVersion = e.target.value;
    CookieManager.setCookie("mapartcraft_mcversion", mcVersion);
    const supportedVersionFound = Object.values(SupportedVersions).find((supportedVersion) => supportedVersion.MCVersion === mcVersion);
    this.setState((currentState) => {
      let selectedBlocks = { ...currentState.selectedBlocks };
      for (const [colourSetId, colourSet] of Object.entries(coloursJSON)) {
        if (selectedBlocks[colourSetId] !== "-1" && !Object.keys(colourSet.blocks[selectedBlocks[colourSetId]].validVersions).includes(mcVersion)) {
          selectedBlocks[colourSetId] = "-1";
        }
      }
      return { optionValue_version: supportedVersionFound, selectedBlocks };
    });
  };

  /* Ручные правки привязаны к сетке, поэтому при смене размера карты
     они неприменимы. Раньше они молча исчезали — предупреждаем. */
  confirmResetPixelEdits = () => {
    if (Object.keys(this.state.pixelEdits).length === 0) return true;
    return window.confirm(this.props.getLocaleString("MAP-SETTINGS/MAP-SIZE-RESETS-EDITS"));
  };

  /* Большая карта съедает много памяти и рисуется долго. Пользователь
     должен понимать, во что он ввязывается, — спрашиваем заранее.
     Диалог один раз: пока размер остаётся «большим», колесо мыши меняет
     размер на единицу, и вопрос на каждом шаге был бы мучением. Когда размер
     снова становится небольшим, вопрос вооружается заново. */
  confirmBigMap = (sizeX, sizeY) => {
    const estimate = estimateMapSize(sizeX, sizeY);
    if (!isBigMap(sizeX, sizeY)) {
      this.bigMapConfirmed = false;
      return true;
    }
    if (this.bigMapConfirmed) return true;
    const memory = estimate.gigabytes >= 1 ? `${estimate.gigabytes.toFixed(1)} GB` : `${Math.round(estimate.megabytes)} MB`;
    const seconds = estimateRenderSeconds(sizeX, sizeY);
    const accepted = window.confirm(
      this.props
        .getLocaleString("MAP-SETTINGS/MAP-SIZE-CONFIRM")
        .replace("{memory}", memory)
        .replace("{seconds}", seconds)
    );
    if (accepted) this.bigMapConfirmed = true;
    return accepted;
  };

  onOptionChange_mapSize_x = (value) => {
    const size = clampMapSize(value);
    if (size === null || size === this.state.optionValue_mapSize_x) return;
    if (!this.confirmResetPixelEdits()) return;
    if (!this.confirmBigMap(size, this.state.optionValue_mapSize_y)) return;
    this.setState({
      optionValue_mapSize_x: size,
      pixelEdits: {},
    });
  };

